"use client"

import * as React from "react"
// Type-only import — erased at compile time, so docx-preview never loads on the
// server (it touches the DOM at call time).
import type * as DocxPreview from "docx-preview"
import { Download, Maximize, Minus, Plus } from "lucide-react"

import { cn } from "@/lib/utils"
import { ViewerFormatError } from "@/lib/viewer-errors"
import {
  createViewerResource,
  type ViewerResource,
} from "@/lib/viewer-resource"
import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source"
import { Button } from "@/components/ui/button"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Separator } from "@/components/ui/separator"
import { Skeleton } from "@/components/ui/skeleton"
import { ViewerDownloadButton } from "@/components/ui/viewer-download"
import { ViewerErrorBoundary } from "@/components/ui/viewer-error"

import { getDocxResource } from "./docx-viewer-resource"

export { getDocxResource } from "./docx-viewer-resource"

// docx-preview is browser-only, so it is imported lazily on the client. jszip
// (its single dependency) is resolved by the bundler from the installed package.
let docxPromise: Promise<typeof DocxPreview> | null = null
function loadDocxPreview() {
  if (!docxPromise) {
    docxPromise = import("docx-preview")
  }
  return docxPromise
}

// We render faithful, paginated pages and override docx-preview's built-in
// chrome (gray backdrop, drop shadow) so pages match the rest of the viewers.
const RENDER_OPTIONS: Partial<DocxPreview.Options> = {
  inWrapper: true,
  breakPages: true,
  ignoreLastRenderedPageBreak: false,
  experimental: true,
  renderHeaders: true,
  renderFooters: true,
  renderFootnotes: true,
}

// Scoped overrides for docx-preview's default wrapper/section styling.
const SCOPED_STYLES = `
[data-slot="docx-viewer"] .docx-wrapper {
  background: transparent;
  padding: 0;
  gap: 1rem;
}
[data-slot="docx-viewer"] .docx-wrapper > section.docx {
  margin-bottom: 0;
  box-shadow: 0 0 0 1px var(--border), 0 1px 2px 0 rgb(0 0 0 / 0.05);
}`

/** Client gate without an effect — false during SSR, true after hydration. */
function useIsClient() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

// --- public API --------------------------------------------------------------

export type DocxDocumentSource = UrlViewerSource | BlobViewerSource

/**
 * Imperative handle for driving the viewer from outside (e.g. scroll to the
 * source of a hovered field). Obtain it with a `ref` on `<DocxViewer>`.
 */
/**
 * A resolved, viewer-ready locator for a docx source — what the `docx-source`
 * adapter produces from an anchor (mirroring how the PDF adapter produces a page
 * `{ page, area }`). The viewer does the DOM resolution, since only it holds the
 * rendered document: a cell by index, or text by content match.
 */
export type DocxTarget =
  | { kind: "text"; text: string }
  | { kind: "cell"; table: number; row: number; column: number }

export interface DocxViewerHandle {
  /**
   * Scroll the element backing a resolved target into view. No-op if it can't be
   * located. Like the other viewers, this takes resolved coordinates (the adapter
   * turns an anchor into a `DocxTarget`), not a raw source.
   */
  scrollToTarget: (target: DocxTarget, options?: ScrollIntoViewOptions) => void
  /** The scrolling viewport element, or null before the document renders. */
  getViewportElement: () => HTMLDivElement | null
}

export interface DocxViewerProps {
  /** Canonical DOCX source. */
  source: DocxDocumentSource
  className?: string
  /** Fixed zoom; when omitted the viewer fits page width to the container. */
  scale?: number
  toolbar?: boolean
  /**
   * A resolved target to highlight in the document. Feed
   * `useSourceLink(...).activeSource` through the `docx-source` adapter's
   * `sourceToDocxHighlight`.
   */
  highlight?: DocxTarget | null
  /** Fired with the 1-based page nearest the top of the viewport as you scroll. */
  onVisiblePageChange?: (page: number) => void
  /** Fired with scroll progress in [0, 1] (for a fine-grained scroll cursor). */
  onScrollProgressChange?: (progress: number) => void
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
  /** Rendered as a full-width strip directly below the toolbar (e.g. a legend). */
  header?: React.ReactNode
  /** Rendered as a left rail alongside the scrolling pages (e.g. a page ribbon). */
  aside?: React.ReactNode
}

// --- source locating ---------------------------------------------------------
// docx-preview renders flowed, paginated HTML with no anchor indices, so a source
// is located in the rendered DOM: table cells by their structural index (reliable
// — docx-preview preserves table/row/cell order), text spans by matching the
// source's quoted `content` (robust to paragraph-index drift between the backend's
// docx parser and the renderer). Both yield a Range the viewer scrolls/highlights.

/** A Range over the contents of the (table, row, column)-indexed cell, or null. */
function tableCellRange(
  root: HTMLElement,
  table: number,
  row: number,
  column: number
): Range | null {
  const t = root.querySelectorAll("table")[table] as
    | HTMLTableElement
    | undefined
  const cell = t?.rows[row]?.cells[column]
  if (!cell) return null
  const range = document.createRange()
  range.selectNodeContents(cell)
  return range
}

/** A Range over the first whitespace-insensitive match of `query` in `root`, or null. */
function textContentRange(root: HTMLElement, query: string): Range | null {
  const needle = query.replace(/\s+/g, " ").trim()
  if (!needle) return null
  // Concatenate the visible text, collapsing whitespace runs to a single space,
  // and remember each normalized character's source (text node + offset) so a
  // match maps back to a DOM Range — even when it spans multiple run <span>s.
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
  let normalized = ""
  const at: { node: Text; offset: number }[] = []
  let prevSpace = false
  for (let n = walker.nextNode(); n; n = walker.nextNode()) {
    const data = (n as Text).data
    for (let i = 0; i < data.length; i++) {
      if (/\s/.test(data[i])) {
        if (prevSpace) continue
        prevSpace = true
        normalized += " "
      } else {
        prevSpace = false
        normalized += data[i]
      }
      at.push({ node: n as Text, offset: i })
    }
  }
  const idx = normalized.indexOf(needle)
  if (idx === -1) return null
  const start = at[idx]
  const end = at[idx + needle.length - 1]
  if (!start || !end) return null
  const range = document.createRange()
  range.setStart(start.node, start.offset)
  range.setEnd(end.node, end.offset + 1)
  return range
}

/** Resolve a target to a DOM Range in the rendered document, or null. */
function targetRange(root: HTMLElement, target: DocxTarget): Range | null {
  return target.kind === "cell"
    ? tableCellRange(root, target.table, target.row, target.column)
    : textContentRange(root, target.text)
}

/** Stable value key for a target, so the highlight effect re-runs on change only. */
function targetKey(target: DocxTarget | null | undefined): string | null {
  if (!target) return null
  return target.kind === "cell"
    ? `cell:${target.table}:${target.row}:${target.column}`
    : `text:${target.text}`
}

export const DocxViewer = React.forwardRef<DocxViewerHandle, DocxViewerProps>(
  function DocxViewer(props, ref) {
    const isClient = useIsClient()
    const resource = React.useMemo(
      () => createViewerResource(props.source),
      [props.source]
    )
    if (!isClient) {
      return (
        <DocxViewerFallback
          bare={props.bare}
          className={props.className}
          toolbar={props.toolbar}
        />
      )
    }
    return (
      <ViewerErrorBoundary
        className={props.className}
        download={resource.getOriginalDownload()}
        format="docx"
        resetKey={resource.cacheKey}
        sourceKind={resource.source.kind}
      >
        <React.Suspense
          fallback={
            <DocxViewerFallback
              bare={props.bare}
              className={props.className}
              toolbar={props.toolbar}
            />
          }
        >
          <DocxViewerInner {...props} forwardedRef={ref} resource={resource} />
        </React.Suspense>
      </ViewerErrorBoundary>
    )
  }
)

function DocxViewerInner({
  resource,
  className,
  scale: fixedScale,
  toolbar = true,
  onVisiblePageChange,
  onScrollProgressChange,
  bare = false,
  header,
  aside,
  highlight,
  forwardedRef,
}: DocxViewerProps & {
  forwardedRef?: React.ForwardedRef<DocxViewerHandle>
  resource: ViewerResource
}) {
  const buffer = React.use(getDocxResource(resource, { retainRejected: true }))

  const [manualScale, setManualScale] = React.useState<number | null>(
    fixedScale ?? null
  )
  React.useEffect(() => {
    setManualScale(fixedScale ?? null)
  }, [fixedScale])
  const [containerWidth, setContainerWidth] = React.useState<number | null>(
    null
  )
  // Known only after docx-preview lays the document out.
  const [numPages, setNumPages] = React.useState(0)
  const [pageWidth, setPageWidth] = React.useState<number | null>(null)
  const [ready, setReady] = React.useState(false)
  const [renderError, setRenderError] = React.useState<Error | null>(null)
  if (renderError) throw renderError

  // Measure the container with a ResizeObserver attached in the ref callback.
  // Coalesce to one update per frame so dragging a resize handle doesn't trigger
  // a fit-width recompute per pixel.
  const containerRef = React.useCallback((el: HTMLDivElement | null) => {
    if (!el) return
    setContainerWidth(el.clientWidth)
    let frame = 0
    let latest = el.clientWidth
    const observer = new ResizeObserver((entries) => {
      // Use clientWidth (content + padding), matching the init read above, so
      // the `- 32` in fitScale subtracts the p-4 padding exactly once. Using
      // entry.contentRect.width here (which already excludes padding) would
      // double-subtract it, shrinking the page 32px below the full content
      // width — and below the w-full skeleton that stands in for it.
      for (const entry of entries)
        latest = (entry.target as HTMLElement).clientWidth
      if (frame) return
      frame = requestAnimationFrame(() => {
        frame = 0
        setContainerWidth(latest)
      })
    })
    observer.observe(el)
    return () => {
      if (frame) cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [])

  // Report the page nearest the top of the scroll viewport as the user scrolls.
  // We watch the actual scroll container (not the browser viewport) so the
  // current-page cursor stays in sync even when the viewer is embedded.
  const scrollViewportRef = React.useRef<HTMLDivElement | null>(null)
  const lastReported = React.useRef(0)
  // The page nearest the top of the viewport, shown as "Page N of M" in the toolbar.
  const [currentPage, setCurrentPage] = React.useState(1)
  // Coalesce scroll work to one frame: the layout reads below (getBoundingClientRect
  // over every page) shouldn't run on every scroll event.
  const scrollFrame = React.useRef(0)
  const measureScroll = React.useCallback(() => {
    scrollFrame.current = 0
    const viewport = scrollViewportRef.current
    if (!viewport) return
    const scrollable = viewport.scrollHeight - viewport.clientHeight
    onScrollProgressChange?.(
      scrollable > 0 ? viewport.scrollTop / scrollable : 0
    )
    const rect = viewport.getBoundingClientRect()
    const marker = rect.top + rect.height * 0.2
    const pages = viewport.querySelectorAll<HTMLElement>("[data-page-number]")
    let current = 1
    for (const el of pages) {
      if (el.getBoundingClientRect().top <= marker) {
        current = Number(el.dataset.pageNumber)
      } else {
        break
      }
    }
    if (current && current !== lastReported.current) {
      lastReported.current = current
      setCurrentPage(current)
      onVisiblePageChange?.(current)
    }
  }, [onVisiblePageChange, onScrollProgressChange])
  const handleScroll = React.useCallback(() => {
    if (scrollFrame.current) return
    scrollFrame.current = requestAnimationFrame(measureScroll)
  }, [measureScroll])
  React.useEffect(
    () => () => {
      if (scrollFrame.current) cancelAnimationFrame(scrollFrame.current)
    },
    []
  )

  const fitScale =
    containerWidth && pageWidth
      ? clamp((containerWidth - 32) / pageWidth, 0.25, 5)
      : 1
  const scale = manualScale ?? fitScale
  // Mirror the live scale into a ref so the render effect can divide measured
  // (zoomed) page sizes back to natural units without re-running on every zoom.
  const scaleRef = React.useRef(scale)
  React.useEffect(() => {
    scaleRef.current = scale
  })

  // Render the document once per source. docx-preview writes imperatively into
  // `host`, which React keeps empty, so the two never fight over the subtree.
  const hostRef = React.useRef<HTMLDivElement | null>(null)
  React.useEffect(() => {
    const host = hostRef.current
    if (!host) return
    let cancelled = false
    setReady(false)
    setNumPages(0)
    setCurrentPage(1)
    lastReported.current = 0
    loadDocxPreview()
      .then(({ renderAsync }) => {
        if (cancelled) return
        const renderHost = document.createElement("div")
        return renderAsync(buffer, renderHost, undefined, RENDER_OPTIONS).then(
          () => renderHost
        )
      })
      .then((renderHost) => {
        if (cancelled || !hostRef.current) return
        if (renderHost)
          host.replaceChildren(...Array.from(renderHost.childNodes))
        // Tag pages for scroll tracking and hand off-screen pages to the browser
        // via `content-visibility` — a long document then only lays out and
        // paints the pages near the viewport. Intrinsic sizes (measured in the
        // page's own, un-zoomed units) keep the scrollbar stable.
        const pages = Array.from(
          host.querySelectorAll<HTMLElement>(".docx-wrapper > section.docx")
        )
        const z = scaleRef.current || 1
        // Two passes so we never interleave reads with writes: measure everything
        // first (one layout), then style everything. Interleaving would force a
        // synchronous reflow per page — O(n) layout thrash on long documents.
        const sizes = pages.map((el) => {
          const r = el.getBoundingClientRect()
          return [Math.round(r.width / z), Math.round(r.height / z)] as const
        })
        pages.forEach((el, i) => {
          el.dataset.pageNumber = String(i + 1)
          el.style.contentVisibility = "auto"
          el.style.containIntrinsicSize = `${sizes[i][0]}px ${sizes[i][1]}px`
        })
        setNumPages(pages.length)
        setPageWidth(pages.length ? sizes[0][0] : null)
        setReady(true)
      })
      .catch((err) => {
        if (!cancelled) {
          setRenderError(
            new ViewerFormatError({
              format: "docx",
              kind: "render_failed",
              message: "Failed to render DOCX.",
              cause: err,
            })
          )
        }
      })
    return () => {
      cancelled = true
    }
  }, [buffer])

  const zoom = (factor: number) =>
    setManualScale(clamp(scale * factor, 0.25, 5))

  // CSS Custom Highlight API: mark the active source's Range without mutating
  // docx-preview's DOM (wrapping nodes would disturb its layout). The registry is
  // global and keyed by name, so each instance uses a unique name + its own
  // `::highlight()` rule (injected in the JSX) to avoid cross-instance collisions.
  const highlightName = "docx-src-" + React.useId().replace(/:/g, "")
  // Keyed on the target's value, not its identity: the adapter builds a fresh
  // DocxTarget object each render, so an identity dep would re-run every render.
  const highlightKey = targetKey(highlight)
  React.useEffect(() => {
    const host = hostRef.current
    const registry =
      typeof CSS !== "undefined" && "highlights" in CSS ? CSS.highlights : null
    if (!registry || typeof Highlight === "undefined" || !host) return
    // Re-runs when the doc becomes `ready`, so a highlight set before render lands.
    if (!highlight || !ready) {
      registry.delete(highlightName)
      return
    }
    const range = targetRange(host, highlight)
    if (range) registry.set(highlightName, new Highlight(range))
    else registry.delete(highlightName)
    return () => {
      registry.delete(highlightName)
    }
    // highlight is read but the value-key gates re-runs; identity would thrash.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [highlightKey, ready, highlightName])

  // Imperative handle: scroll the element backing a resolved target into view.
  // `scrollIntoView` (not manual math) so it also reveals content on
  // `content-visibility: auto` pages, whose off-screen geometry isn't measurable.
  React.useImperativeHandle(
    forwardedRef,
    () => ({
      scrollToTarget: (target, options) => {
        const host = hostRef.current
        if (!host) return
        const node = targetRange(host, target)?.startContainer
        const el =
          node?.nodeType === Node.ELEMENT_NODE
            ? (node as HTMLElement)
            : (node?.parentElement ?? null)
        el?.scrollIntoView({
          block: "center",
          inline: "nearest",
          behavior: options?.behavior ?? "smooth",
          ...options,
        })
      },
      getViewportElement: () => scrollViewportRef.current,
    }),
    []
  )

  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="docx-viewer"
    >
      <style>{SCOPED_STYLES}</style>
      {/* Per-instance source-highlight tint (CSS Custom Highlight API). */}
      <style>{`::highlight(${highlightName}){background-color:color-mix(in oklab, var(--primary) 22%, transparent);}`}</style>
      {toolbar ? (
        <div className="flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
          <span className="px-1 text-xs text-muted-foreground tabular-nums">
            {ready ? (
              <>
                Page {Math.min(currentPage, numPages)} of {numPages}
              </>
            ) : (
              // Page count is unknown until docx-preview lays out — skeleton it.
              <Skeleton className="inline-block h-3 w-12 align-middle" />
            )}
          </span>
          <div className="ml-auto flex items-center gap-1">
            <IconButton label="Zoom out" onClick={() => zoom(1 / 1.2)}>
              <Minus />
            </IconButton>
            <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
              {ready ? (
                `${Math.round(scale * 100)}%`
              ) : (
                // Fit-width % depends on the measured page width — skeleton it.
                <Skeleton className="inline-block h-3 w-8 align-middle" />
              )}
            </span>
            <IconButton label="Zoom in" onClick={() => zoom(1.2)}>
              <Plus />
            </IconButton>
            <IconButton label="Fit width" onClick={() => setManualScale(null)}>
              <Maximize />
            </IconButton>
            <Separator orientation="vertical" className="mx-1 h-4" />
            <ViewerDownloadButton action={resource.getOriginalDownload()} />
          </div>
        </div>
      ) : null}

      <div className="flex min-h-0 flex-1">
        {aside ? (
          <div data-slot="docx-viewer-aside" className="flex-shrink-0">
            {aside}
          </div>
        ) : null}
        <div className="flex min-h-0 min-w-0 flex-1 flex-col">
          {header ? <div data-slot="docx-viewer-header">{header}</div> : null}
          <ScrollArea
            className="min-h-0 flex-1"
            viewportRef={scrollViewportRef}
            // Always track scroll so the toolbar's "Page N of M" updates.
            viewportProps={{ onScroll: handleScroll }}
          >
            <div ref={containerRef} className="flex flex-col items-center p-4">
              {/* A document-shaped skeleton stands in for the pages until
                  docx-preview lays them out. Rendered before the host (which is
                  taller than the viewport) so the invisible, not-yet-measured
                  host stays below the fold during the brief measure window. */}
              {!ready ? <DocxSkeleton /> : null}
              {/* docx-preview renders the .docx-wrapper into this host; `zoom`
                  scales the laid-out pages (and scroll height) cheaply. Kept
                  invisible (not display:none — it must stay measurable) until
                  `ready`, so the first frame the user sees is already at the
                  measured fit-width zoom. Otherwise the page paints at zoom 1,
                  then snaps to fit once measured — the load flicker/resize. */}
              <div
                ref={hostRef}
                className={cn(
                  "w-full transition-opacity duration-200",
                  ready ? "opacity-100" : "opacity-0"
                )}
                style={{ zoom: scale }}
              />
            </div>
          </ScrollArea>
        </div>
      </div>
    </div>
  )
}

function IconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}

// Shown while the document resource and docx-preview load (before DocxViewerInner
// mounts). Same chrome as the loaded viewer — a toolbar with skeletoned values
// plus a document-shaped skeleton — so the topbar is always present and there is
// no spinner anywhere; nothing jumps when the real document fades in.
function DocxViewerFallback({
  className,
  bare = false,
  toolbar = true,
}: {
  className?: string
  bare?: boolean
  toolbar?: boolean
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="docx-viewer"
    >
      {toolbar ? <DocxToolbarSkeleton /> : null}
      <div className="min-h-0 flex-1 overflow-auto">
        <div className="flex flex-col items-center p-4">
          <DocxSkeleton />
        </div>
      </div>
    </div>
  )
}

// A static mirror of the real toolbar: the two undetermined values (page count,
// zoom %) are skeletons; the controls are present but inert.
function DocxToolbarSkeleton() {
  return (
    <div className="flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
      <span className="px-1">
        <Skeleton className="inline-block h-3 w-12 align-middle" />
      </span>
      <div className="ml-auto flex items-center gap-1">
        <ToolbarIconPlaceholder>
          <Minus />
        </ToolbarIconPlaceholder>
        <span className="w-12 text-center">
          <Skeleton className="inline-block h-3 w-8 align-middle" />
        </span>
        <ToolbarIconPlaceholder>
          <Plus />
        </ToolbarIconPlaceholder>
        <ToolbarIconPlaceholder>
          <Maximize />
        </ToolbarIconPlaceholder>
        <Separator orientation="vertical" className="mx-1 h-4" />
        <ToolbarIconPlaceholder>
          <Download />
        </ToolbarIconPlaceholder>
      </div>
    </div>
  )
}

function ToolbarIconPlaceholder({ children }: { children: React.ReactNode }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      disabled
      tabIndex={-1}
      aria-hidden
    >
      {children}
    </Button>
  )
}

// A plain gray page-shaped block stands in for the document while it loads.
// The sample is US Letter (w:pgSz 12240 × 15840 twips = 8.5" × 11"), so the
// aspect matches the rendered page; `w-full` inside the container's p-4 equals
// the fit-width page width — so the block is the same size as the document that
// replaces it. (For A4 docs this would be 210 / 297.)
function DocxSkeleton() {
  return (
    <Skeleton
      aria-hidden
      className="w-full rounded-sm"
      style={{ aspectRatio: "8.5 / 11" }}
    />
  )
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

import { type ViewerResource } from "@/lib/viewer-resource"

const bufferCache = new Map<string, Promise<ArrayBuffer>>()

export function getDocxResource(
  resource: ViewerResource,
  options: { retainRejected?: boolean } = {}
): Promise<ArrayBuffer> {
  const resourceKey = resource.cacheKey
  const cached = bufferCache.get(resourceKey)
  if (cached) return cached

  const promise = resource.readArrayBuffer().catch((error) => {
    if (!options.retainRejected && bufferCache.get(resourceKey) === promise)
      bufferCache.delete(resourceKey)
    throw error
  })
  bufferCache.set(resourceKey, promise)
  return promise
}

export function __resetDocxResourceCacheForTests() {
  bufferCache.clear()
}

"use client"

import * as React from "react"
import { Download } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  ViewerDownloadError,
  type ViewerDownloadAction,
  type ViewerDownloadPayload,
} from "@/lib/viewer-download"
import { Button, buttonVariants } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

export async function triggerViewerDownload(
  action: ViewerDownloadAction,
  options?: { signal?: AbortSignal }
): Promise<void> {
  if (action.isDisabled) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "disabled",
      message: "This download is disabled.",
    })
  }

  let payload: ViewerDownloadPayload
  try {
    payload = await action.getPayload(options)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "aborted",
        message: "Download was cancelled.",
        cause: error,
      })
    }
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "payload_failed",
      message: "Could not prepare this download.",
      cause: error,
    })
  }

  if (payload.kind === "none") return
  if (payload.kind === "href") {
    clickDownload(payload.href, action.fileName)
    return
  }

  const blob =
    payload.kind === "blob"
      ? payload.blob
      : new Blob([payload.text], {
          type: payload.mimeType ?? "text/plain;charset=utf-8",
        })
  const url = URL.createObjectURL(blob)
  try {
    clickDownload(url, action.fileName)
  } finally {
    URL.revokeObjectURL(url)
  }
}

export function useViewerDownloadHref(
  action: ViewerDownloadAction | null
): string | null {
  const shouldCreateHref = action?.origin !== "derived"
  const payload = shouldCreateHref ? getSynchronousPayload(action) : null

  return shouldCreateHref && payload?.kind === "href" ? payload.href : null
}

export function ViewerDownloadControl({
  actions,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
}: {
  actions: Array<ViewerDownloadAction | null | undefined>
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  showLabel?: boolean
}) {
  const enabledActions = actions.filter(
    (action): action is ViewerDownloadAction => Boolean(action)
  )

  if (enabledActions.length <= 1) {
    return (
      <ViewerDownloadButton
        action={enabledActions[0] ?? null}
        variant={variant}
        size={size}
        className={className}
        showLabel={showLabel}
      />
    )
  }

  return (
    <ViewerDownloadMenu
      actions={enabledActions}
      variant={variant}
      size={size}
      className={className}
      showLabel={showLabel}
    />
  )
}

export function ViewerDownloadButton({
  action,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
}: {
  action: ViewerDownloadAction | null
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  showLabel?: boolean
}) {
  const [isPending, setIsPending] = React.useState(false)
  const href = useViewerDownloadHref(action)
  const label = action?.label ?? "Download"
  const disabled = !action || action.isDisabled
  const hasDownloadHref = Boolean(href)

  const handleClick = React.useCallback(() => {
    if (!action || hasDownloadHref) return
    setIsPending(true)
    void triggerViewerDownload(action)
      .catch(() => undefined)
      .finally(() => setIsPending(false))
  }, [action, hasDownloadHref])

  if (href) {
    return (
      <a
        href={href}
        download={action?.fileName}
        className={cn(buttonVariants({ variant, size }), className)}
        aria-label={label}
        title={label}
        data-slot="button"
      >
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
        {showLabel ? label : null}
      </a>
    )
  }

  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      aria-label={label}
      title={label}
      disabled={disabled}
      loading={isPending}
      onClick={handleClick}
    >
      <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
      {showLabel ? label : null}
    </Button>
  )
}

export function ViewerDownloadMenu({
  actions,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
}: {
  actions: ViewerDownloadAction[]
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  showLabel?: boolean
}) {
  const [pendingActionId, setPendingActionId] = React.useState<string | null>(
    null
  )
  const label = "Download"

  const trigger = (action: ViewerDownloadAction) => {
    setPendingActionId(action.id)
    void triggerViewerDownload(action)
      .catch(() => undefined)
      .finally(() => setPendingActionId(null))
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant={variant}
            size={size}
            className={className}
            aria-label={label}
            title={label}
            loading={pendingActionId != null}
          >
            <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
            {showLabel ? label : null}
          </Button>
        }
      />
      <DropdownMenuContent align="end">
        {actions.map((action) => (
          <DropdownMenuItem
            key={action.id}
            disabled={action.isDisabled || pendingActionId != null}
            onClick={() => trigger(action)}
          >
            <Download />
            <span>{action.label}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function clickDownload(href: string, fileName: string) {
  const anchor = document.createElement("a")
  anchor.href = href
  anchor.download = fileName
  anchor.rel = "noreferrer"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
}

function getSynchronousPayload(
  action: ViewerDownloadAction | null
): ViewerDownloadPayload | null {
  if (!action || action.isDisabled) return null
  const payload = action.getPayload()
  return payload instanceof Promise ? null : payload
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError"
}

import {
  createBlobDownloadAction,
  createHrefDownloadAction,
  createTextDownloadAction,
  type ViewerDownloadAction,
} from "@/lib/viewer-download"
import {
  isAbortError,
  ResourceError,
  type ResourceTooLargeReason,
} from "@/lib/viewer-errors"
import {
  resolveViewerDescriptor,
  type BlobViewerSource,
  type TextSource,
  type UrlViewerSource,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source"

export interface ResourceReadOptions {
  signal?: AbortSignal
}

export interface TextReadOptions extends ResourceReadOptions {
  maxBytes?: number
  maxLines?: number
}

export interface ByteRange {
  start: number
  end: number
}

export interface ByteRangeResult {
  buffer: ArrayBuffer
  contentRange?: {
    start: number
    end: number
    total: number | null
  }
  isComplete: boolean
}

export type DirectLoadCapability =
  | { kind: "url"; url: string }
  | { kind: "none" }

export interface ViewerResource {
  readonly source: ViewerSource
  readonly descriptor: ViewerDescriptor
  readonly cacheKey: string
  readonly identityKey: string
  readonly fileName: string
  readonly mimeType?: string

  getDirectLoad(): DirectLoadCapability
  getOriginalDownload(): ViewerDownloadAction
  readBlob(options?: ResourceReadOptions): Promise<Blob>
  readArrayBuffer(options?: ResourceReadOptions): Promise<ArrayBuffer>
  readText(options?: TextReadOptions): Promise<string>
  stream(options?: ResourceReadOptions): Promise<ReadableStream<Uint8Array>>
  readRange(
    range: ByteRange,
    options?: ResourceReadOptions
  ): Promise<ByteRangeResult>
}

const URL_RESOURCE_REGISTRY_MAX = 128
const TEXT_LINE_BREAK_PATTERN = /\r\n|\n|\r/g

const urlViewerResourceRegistry = new Map<string, ViewerResource>()
let blobViewerResourceRegistry = new WeakMap<
  Blob,
  Map<string, ViewerResource>
>()
const blobObjectKeys = new WeakMap<Blob, string>()
let nextBlobObjectKey = 0

export function createViewerResource(source: ViewerSource): ViewerResource {
  const descriptor = resolveViewerDescriptor({ source })
  const cacheKey = viewerResourceCacheKey(source)
  const registryKey = viewerResourceRegistryKey(source, descriptor, cacheKey)

  if (source.kind === "url") {
    return internUrlResource(source, descriptor, cacheKey, registryKey)
  }
  if (source.kind === "blob") {
    return internBlobResource(source, descriptor, cacheKey, registryKey)
  }
  return createUncachedViewerResource(source, descriptor, cacheKey)
}

export function clearViewerResourceRegistryForTests() {
  urlViewerResourceRegistry.clear()
  blobViewerResourceRegistry = new WeakMap()
}

function createUncachedViewerResource(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
  cacheKey: string
): ViewerResource {
  switch (source.kind) {
    case "url":
      return createUrlResource(source, descriptor, cacheKey)
    case "blob":
      return createBlobResource(source, descriptor, cacheKey)
    case "text":
      return createTextResource(source, descriptor, cacheKey)
  }
}

function internUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor,
  cacheKey: string,
  registryKey: string
): ViewerResource {
  const cached = urlViewerResourceRegistry.get(registryKey)
  if (cached) return cached

  const resource = createUrlResource(source, descriptor, cacheKey)
  urlViewerResourceRegistry.set(registryKey, resource)
  pruneUrlResourceRegistry()
  return resource
}

function internBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor,
  cacheKey: string,
  registryKey: string
): ViewerResource {
  let resources = blobViewerResourceRegistry.get(source.blob)
  if (!resources) {
    resources = new Map()
    blobViewerResourceRegistry.set(source.blob, resources)
  }

  const cached = resources.get(registryKey)
  if (cached) return cached

  const resource = createBlobResource(source, descriptor, cacheKey)
  resources.set(registryKey, resource)
  return resource
}

function pruneUrlResourceRegistry() {
  while (urlViewerResourceRegistry.size > URL_RESOURCE_REGISTRY_MAX) {
    const firstKey = urlViewerResourceRegistry.keys().next().value
    if (!firstKey) return
    urlViewerResourceRegistry.delete(firstKey)
  }
}

function viewerResourceCacheKey(source: ViewerSource) {
  return [
    source.kind,
    source.identityKey ?? "",
    directLoadCacheKey(source),
    payloadCacheKey(source),
  ].join("\u0000")
}

function viewerResourceRegistryKey(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
  cacheKey: string
) {
  return [
    cacheKey,
    descriptor.category,
    descriptor.displayName,
    descriptor.fileName,
    descriptor.mimeType ?? "",
    downloadCacheKey(source),
  ].join("\u0000")
}

function directLoadCacheKey(source: ViewerSource) {
  return source.kind === "url" ? source.url : ""
}

function downloadCacheKey(source: ViewerSource) {
  if (source.kind === "text") return ""
  return source.downloadUrl ?? ""
}

function payloadCacheKey(source: ViewerSource) {
  if (source.kind === "url") return ""
  if (source.kind === "blob") return blobObjectKey(source.blob)
  return `text:${source.text.length}:${hashString(source.text)}`
}

function blobObjectKey(blob: Blob) {
  let key = blobObjectKeys.get(blob)
  if (!key) {
    nextBlobObjectKey += 1
    key = `blob-object:${nextBlobObjectKey}`
    blobObjectKeys.set(blob, key)
  }
  return key
}

function hashString(text: string) {
  let hash = 0x811c9dc5
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(36)
}

export function blobSource(
  bytes: Blob | ArrayBuffer | Uint8Array,
  metadata: {
    identityKey: string
    fileName?: string
    mimeType?: string
    downloadUrl?: string
  }
): BlobViewerSource {
  const blob =
    bytes instanceof Blob
      ? bytes
      : new Blob(
          [bytes instanceof ArrayBuffer ? bytes : new Uint8Array(bytes)],
          {
            type: metadata.mimeType ?? "",
          }
        )
  return {
    kind: "blob",
    blob,
    fileName: metadata.fileName,
    mimeType: metadata.mimeType ?? blob.type,
    downloadUrl: metadata.downloadUrl,
    identityKey: metadata.identityKey,
  }
}

function createUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor,
  cacheKey: string
): ViewerResource {
  return resourceBase(source, descriptor, cacheKey, {
    getDirectLoad: () => ({ kind: "url", url: source.url }),
    getOriginalDownload: () =>
      createHrefDownloadAction({
        id: "download-original",
        label: "Download",
        href: source.downloadUrl ?? source.url,
        fileName: descriptor.fileName,
      }),
    readBlob: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return response.blob()
    },
    readArrayBuffer: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return response.arrayBuffer()
    },
    readText: async ({ signal, maxBytes, maxLines } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return readBoundedResponseText(response, { maxBytes, maxLines })
    },
    stream: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      if (!response.body) {
        throw new ResourceError({
          kind: "unsupported_capability",
          message: "This response cannot be streamed.",
        })
      }
      return response.body
    },
    readRange: async ({ start, end }, { signal } = {}) => {
      const response = await fetchResource(source.url, {
        signal,
        headers: { Range: `bytes=${start}-${end}` },
      })
      const buffer = await response.arrayBuffer()
      return {
        buffer,
        contentRange: parseContentRange(response.headers.get("content-range")),
        isComplete: response.status === 200 || buffer.byteLength <= end - start,
      }
    },
  })
}

function createBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor,
  cacheKey: string
): ViewerResource {
  const blob = source.blob
  return resourceBase(source, descriptor, cacheKey, {
    getDirectLoad: () => ({ kind: "none" }),
    getOriginalDownload: () =>
      source.downloadUrl
        ? createHrefDownloadAction({
            id: "download-original",
            label: "Download",
            href: source.downloadUrl,
            fileName: descriptor.fileName,
          })
        : createBlobDownloadAction({
            id: "download-original",
            label: "Download",
            blob,
            fileName: descriptor.fileName,
          }),
    readBlob: async () => blob,
    readArrayBuffer: async () => blob.arrayBuffer(),
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedBlobText(blob, { maxBytes, maxLines }),
    stream: async () => blob.stream(),
    readRange: async ({ start, end }) => {
      const rangeBlob = blob.slice(start, end + 1)
      return {
        buffer: await rangeBlob.arrayBuffer(),
        contentRange: {
          start,
          end: Math.min(end, Math.max(0, blob.size - 1)),
          total: blob.size,
        },
        isComplete: end >= blob.size - 1,
      }
    },
  })
}

function createTextResource(
  source: TextSource,
  descriptor: ViewerDescriptor,
  cacheKey: string
): ViewerResource {
  return resourceBase(source, descriptor, cacheKey, {
    getDirectLoad: () => ({ kind: "none" }),
    getOriginalDownload: () =>
      createTextDownloadAction({
        id: "download-original",
        label: "Download",
        text: source.text,
        fileName: descriptor.fileName,
        mimeType: descriptor.mimeType,
      }),
    readBlob: async () =>
      new Blob([source.text], {
        type: descriptor.mimeType ?? "text/plain;charset=utf-8",
      }),
    readArrayBuffer: async () => new TextEncoder().encode(source.text).buffer,
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedInlineText(source.text, { maxBytes, maxLines }),
    stream: async () => new Blob([source.text]).stream(),
    readRange: async ({ start, end }) => {
      const buffer = new TextEncoder().encode(source.text)
      const slice = buffer.slice(start, end + 1)
      return {
        buffer: slice.buffer,
        contentRange: {
          start,
          end: Math.min(end, Math.max(0, buffer.byteLength - 1)),
          total: buffer.byteLength,
        },
        isComplete: end >= buffer.byteLength - 1,
      }
    },
  })
}

function resourceBase(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
  cacheKey: string,
  methods: Pick<
    ViewerResource,
    | "getDirectLoad"
    | "getOriginalDownload"
    | "readBlob"
    | "readArrayBuffer"
    | "readText"
    | "stream"
    | "readRange"
  >
): ViewerResource {
  return Object.freeze({
    source,
    descriptor,
    cacheKey,
    identityKey: descriptor.identityKey,
    fileName: descriptor.fileName,
    mimeType: descriptor.mimeType,
    ...methods,
  })
}

async function fetchResource(
  input: RequestInfo | URL,
  init?: RequestInit
): Promise<Response> {
  let response: Response
  try {
    response = await fetch(input, init)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ResourceError({
        kind: "aborted",
        message: "Loading was cancelled.",
        cause: error,
      })
    }
    throw new ResourceError({
      kind: "fetch_failed",
      message: "Could not fetch this resource.",
      cause: error,
    })
  }

  if (!response.ok && response.status !== 206) {
    throw new ResourceError({
      kind: "http_error",
      message: `Failed to load resource: ${response.status}`,
      status: response.status,
    })
  }

  return response
}

async function readBoundedResponseText(
  response: Response,
  bounds: { maxBytes?: number; maxLines?: number }
) {
  if (response.status === 206) {
    throw new ResourceError({
      kind: "partial_content",
      message: "Full text response returned partial content.",
      status: response.status,
    })
  }

  const maxBytes = bounds.maxBytes
  const contentLength = response.headers.get("content-length")
  const contentByteLength = contentLength ? Number(contentLength) : null
  if (
    maxBytes != null &&
    contentByteLength != null &&
    Number.isFinite(contentByteLength) &&
    contentByteLength > maxBytes
  ) {
    throw tooLarge("bytes")
  }

  const body = response.body
  if (!body) {
    const buffer = await response.arrayBuffer()
    if (maxBytes != null && buffer.byteLength > maxBytes) {
      throw tooLarge("bytes")
    }
    return readBoundedInlineText(new TextDecoder().decode(buffer), bounds)
  }

  const reader = body.getReader()
  const decoder = new TextDecoder()
  let receivedBytes = 0
  let text = ""

  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    receivedBytes += value.byteLength
    if (maxBytes != null && receivedBytes > maxBytes) {
      await reader.cancel()
      throw tooLarge("bytes")
    }
    text += decoder.decode(value, { stream: true })
  }

  text += decoder.decode()
  return readBoundedInlineText(text, bounds)
}

async function readBoundedBlobText(
  blob: Blob,
  bounds: { maxBytes?: number; maxLines?: number }
) {
  if (bounds.maxBytes != null && blob.size > bounds.maxBytes) {
    throw tooLarge("bytes")
  }
  return readBoundedInlineText(await blob.text(), bounds)
}

function readBoundedInlineText(
  text: string,
  { maxBytes, maxLines }: { maxBytes?: number; maxLines?: number }
) {
  if (
    maxBytes != null &&
    new TextEncoder().encode(text).byteLength > maxBytes
  ) {
    throw tooLarge("bytes")
  }
  if (
    maxLines != null &&
    text.split(TEXT_LINE_BREAK_PATTERN).length > maxLines
  ) {
    throw tooLarge("lines")
  }
  return text
}

function tooLarge(reason: ResourceTooLargeReason) {
  return new ResourceError({
    kind: "too_large",
    tooLargeReason: reason,
    message: `Resource exceeds ${reason} limit.`,
  })
}

function parseContentRange(value: string | null) {
  if (!value) return undefined
  const match = value.match(/bytes\s+(\d+)-(\d+)\/(\d+|\*)/i)
  if (!match) return undefined
  return {
    start: Number(match[1]),
    end: Number(match[2]),
    total: match[3] === "*" ? null : Number(match[3]),
  }
}
